import * as L from 'leaflet';
import * as Astronomy from 'astronomy-engine';

// Initialize the map
const map = L.map('map').setView([0, 0], 2); // Centered at [0, 0] with zoom level 2

L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
    maxZoom: 19
}).addTo(map);

// Function to update Sun and Moon positions
function updateSunMoonPositions() {
    const date = new Date();
    const observer = new Astronomy.Observer(0, 0, 0); // Example observer at equator

    // Sun position
    const sunEquatorial = Astronomy.Equator(Astronomy.Body.Sun, date, observer, true, true);
    const sunHorizon = Astronomy.Horizon(date, observer, sunEquatorial.ra, sunEquatorial.dec, 'normal');
    const sunLatLng = [sunHorizon.altitude * (180 / Math.PI), sunHorizon.azimuth * (180 / Math.PI)];

    // Moon position
    const moonEquatorial = Astronomy.Equator(Astronomy.Body.Moon, date, observer, true, true);
    const moonHorizon = Astronomy.Horizon(date, observer, moonEquatorial.ra, moonEquatorial.dec, 'normal');
    const moonLatLng = [moonHorizon.altitude * (180 / Math.PI), moonHorizon.azimuth * (180 / Math.PI)];

    // Add markers to the map
    L.marker([sunLatLng[0], sunLatLng[1]]).addTo(map)
        .bindPopup('Sun Position')
        .openPopup();

    L.marker([moonLatLng[0], moonLatLng[1]]).addTo(map)
        .bindPopup('Moon Position')
        .openPopup();
}

// Initial call to update positions
updateSunMoonPositions();

// Update positions every minute
setInterval(updateSunMoonPositions, 60000);
